sysauto_script.script:
// SLAWatch — scheduled daily scan
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function () {
    try {
        var engine = new SlaWatchEngine();
        var scanSysId = engine.runFullScan('delta', 30);
        if (scanSysId) {
            gs.info('SLAWatch daily scan completed: ' + scanSysId);
        } else {
            gs.error('SLAWatch daily scan failed to create scan record');
        }
    } catch (e) {
        gs.error('SLAWatch daily scan error: ' + e.message);
    }
})();
